-- Warranty Tracker indexes. Apply after V20260717_05. Test environment only.
CREATE INDEX IF NOT EXISTS idx_warranty_tracker_active_state ON warranty_claims(active,state);CREATE INDEX IF NOT EXISTS idx_warranty_tracker_result ON warranty_claims(result);CREATE INDEX IF NOT EXISTS idx_warranty_tracker_owner ON warranty_claims(warranty_owner_employee_id);CREATE INDEX IF NOT EXISTS idx_warranty_tracker_follow_up ON warranty_claims(next_follow_up_date) WHERE active=true;CREATE INDEX IF NOT EXISTS idx_warranty_tracker_visit ON warranty_claims(expected_visit_date) WHERE active=true;CREATE INDEX IF NOT EXISTS idx_warranty_tracker_replacement_due ON warranty_claims(expected_replacement_date) WHERE active=true;CREATE INDEX IF NOT EXISTS idx_warranty_tracker_created ON warranty_claims(created_at);CREATE INDEX IF NOT EXISTS idx_warranty_tracker_updated ON warranty_claims(updated_at);CREATE INDEX IF NOT EXISTS idx_warranty_tracker_manufacturer_lower ON warranty_claims(lower(manufacturer_name));CREATE INDEX IF NOT EXISTS idx_warranty_tracker_complaint_lower ON warranty_claims(lower(manufacturer_complaint_number));CREATE INDEX IF NOT EXISTS idx_warranty_tracker_ticket_number_lower ON tickets(lower(ticket_number));CREATE INDEX IF NOT EXISTS idx_warranty_tracker_mobile ON tickets(mobile_number);CREATE INDEX IF NOT EXISTS idx_warranty_tracker_customer_lower ON tickets(lower(customer_name));
